{"implementation":"def solve(case):
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])
    nodes_by_id = {node['id']: node for node in nodes}
    children_map = {}
    for node in nodes:
        parent = node['parent']
        if parent is not None:
            children_map.setdefault(parent, []).append(node['id'])
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    removed_set = set()
    removed_order = []
    for node in sorted_nodes:
        nid = node['id']
        if node['parent'] is None:
            continue
        if node['symbol'] in required_symbols:
            continue
        if not node['removable']:
            continue
        children = children_map.get(nid, [])
        if any(cid not in removed_set for cid in children):
            continue
        removed_set.add(nid)
        removed_order.append(nid)
    retained_ids = sorted(nid for nid in nodes_by_id if nid not in removed_set)
    return {
        'removed_node_ids': removed_order,
        'retained_node_ids': retained_ids
    }"}
